CREATE TABLE IF NOT EXISTS {schema}.sell_orders (id {uuid} PRIMARY KEY, market_name {keyed} NOT NULL REFERENCES {schema}.markets(name), seller {uuid} NOT NULL, material {keyed} NOT NULL, item_blob {blob} NOT NULL, fingerprint {keyed} NOT NULL, quantity {integer} NOT NULL CHECK (quantity > 0), quantity_remaining {integer} NOT NULL CHECK (quantity_remaining >= 0), unit_price {numeric} NOT NULL CHECK (unit_price > 0), mode {status} NOT NULL CHECK (mode IN ('NORMAL', 'INSTANT')), status {status} NOT NULL CHECK (status IN ('CREATING', 'ACTIVE', 'FILLED', 'CANCELED', 'EXPIRED', 'VOIDED')), expires_at {ts} NOT NULL, created_at {ts} NOT NULL{defaultNow}, CHECK (quantity_remaining <= quantity))
